#include "ProjectCommands.h"
static void testProjectCommands(const File& root,Assets& assets){
    auto source=emptyProject();source.patterns[0].lanes[7]={{.5,.75,60,.7f,.4f,3,4,2},{3,.5,67,.6f},{6,.25,72,.8f}};source.clips={{7,0,0,8}};source.markers={{"chorus","Chorus",0,8,3}};auto before=JSON::toString(projectToJson(source));
    const char* corpus[]={"set tempo to 30 bpm","SET TEMPO TO 300","set tempo to 120.5 bpm","set loop off","set metronome on","set track 8 volume to 60 percent","set track 8 pan to -100 percent","set track 8 send to 80 percent","set track 8 cutoff to 60 hz","set track 8 cutoff to 20000 hz","lower track \"Bass\" by 2 db","raise track 8 by 2 db","mute track 2","unmute track 2","solo track 8","unsolo track 8","rename song to \"New song\"","rename track 8 to \"New lead\"","rename pattern 1 to \"Verse\"","set pattern 1 length to 16 beats","transpose track 8 in pattern 1 up 2 semitones","transpose track \"Lead\" in pattern 1 down 2 semitones","use sound \"cedar string\" on track 8","copy section \"chorus\" to beat 16","move section \"Chorus\" to beat 16"};
    for(auto text:corpus){ProjectCommandDraft draft;expect(buildProjectCommands(source,text,draft).wasOk()&&draft.operations.isArray()&&draft.operations.getArray()->size()==1&&draft.resolved.size()==1, text);}
    expect(JSON::toString(projectToJson(source))==before,"parsing the declared command corpus never changes the source project");
    ProjectCommandDraft draft;auto commands=String::fromUTF8("rename track 8 to \"Струны\"\nlower track \"струны\" by 2 db\nuse sound \"Cedar string\" on track \"Струны\"\ntranspose track 8 in pattern 1 up 2 semitones");auto sequential=buildProjectCommands(source,commands,draft);if(sequential.failed()){std::cerr<<"Command sequence error: "<<sequential.getErrorMessage()<<"\n";}expect(sequential.wasOk()&&draft.resolved.size()==4&&draft.project.tracks[7].instrument==Instrument::physical&&std::abs(draft.project.tracks[7].volume-source.tracks[7].volume*std::pow(10.,-.1))<1e-6,"commands resolve names sequentially, including Unicode and factory sounds");if(sequential.failed())return;auto notes=draft.project.patterns[0].lanes[7];for(auto& n:notes)n.pitch-=2;expect(notes==source.patterns[0].lanes[7],"command transposition preserves timing, velocity, chance, ratchets and repeat conditions exactly");
    auto quoted=source;quoted.tracks[7].name="A \"quoted\" \\ name";expect(buildProjectCommands(quoted,R"(mute track "A \"quoted\" \\ name")",draft).wasOk()&&draft.project.tracks[7].mute,"quoted target names support literal quote and backslash escapes");
    auto duplicate=source;duplicate.tracks[6].name="Lead";expect(buildProjectCommands(duplicate,"mute track \"lead\"",draft).failed()&&buildProjectCommands(duplicate,"mute track 8",draft).wasOk(),"ambiguous track names require a visible number");auto pattern=source.patterns[0];duplicate=source;duplicate.patterns.push_back(pattern);expect(buildProjectCommands(duplicate,"rename pattern \"Pattern 01\" to \"A\"",draft).failed(),"duplicate pattern names never resolve silently to the first match");
    for(auto text:{"", "   ","set tempo to nan","set tempo to inf","set tempo to 29","set tempo to 301","set tempo to 120 junk","set tempo to \"120\"","set tempo to 120; mute track 1","mute track 0","mute track 17","mute track -1","mute track 1.5","mute track \"missing\"","mute track Bass","mute track \"Bass","mute track \"Bass\"junk","rename track 8 to NoQuotes","set track 8 volume to 151 percent","set track 8 volume to -1 percent","set track 8 pan to 101 percent","set track 8 send to 81 percent","set track 8 cutoff to 59 hz","set track 8 cutoff to 20001 hz","set track 8 volume to 50","set track 8 drive to 50 percent","lower track 8 by -2 db","raise track 8 by 97 db","raise track 8 by 96 db","set pattern 1 length to 4 beats","set pattern 1 length to 65 beats","transpose track 8 in pattern 1 up 1.5 semitones","transpose track 8 in pattern 1 down 49 semitones","transpose track 8 in pattern 1 sideways 1 semitones","use sound \"unknown\" on track 8","copy section \"missing\" to beat 16","copy section \"Chorus\" to beat 0","move section \"Chorus\" to beat -1","set loop maybe","delete all files","export song to c:\\song.wav","run powershell","set tempo to 120\nunknown request"}){ProjectCommandDraft sentinel;sentinel.project.title="Retain draft";sentinel.resolved.add("Retain summary");auto valid=buildProjectCommands(source,text,sentinel);expect(valid.failed()&&sentinel.project.title=="Retain draft"&&sentinel.resolved[0]=="Retain summary"&&JSON::toString(projectToJson(source))==before,"unsupported, invalid or ambiguous text rejects atomically without draft/source changes");}
    String sixteen;for(int i=0;i<16;++i)sixteen+="set tempo to "+String(100+i)+" bpm\n";expect(buildProjectCommands(source,sixteen,draft).wasOk()&&draft.project.bpm==115&&draft.resolved.size()==16,"sixteen ordered commands are accepted as one bounded draft");expect(buildProjectCommands(source,sixteen+"set loop on",draft).failed()&&buildProjectCommands(source,String::repeatedString("x",4097),draft).failed(),"command counts and text lengths are bounded");
    auto op=JSON::parse(R"([{"op":"project_commands","text":"rename track 8 to \"Strings\"\nset track \"Strings\" volume to 55 percent\ntranspose track 8 in pattern 1 down 3 semitones"}])");Project edited;StringArray summary;expect(applyControlEdits(source,op,edited,&summary).wasOk()&&summary.size()==3&&edited.tracks[7].name=="Strings"&&edited.patterns[0].lanes[7][0].pitch==57,"MCP text operation shares the same domain parser and target resolution");
    auto sentinel=JSON::toString(projectToJson(edited));summary=StringArray{"retain"};(*op.getArray())[0].getDynamicObject()->setProperty("text","set tempo to 120\nset track 8 volume to 200 percent");expect(applyControlEdits(source,op,edited,&summary).failed()&&summary[0]=="retain"&&JSON::toString(projectToJson(edited))==sentinel,"a late invalid text command cannot partially replace an MCP destination or resolved summary");
    Array<var> oversized;for(int i=0;i<2;++i){auto* o=new DynamicObject();o->setProperty("op","project_commands");o->setProperty("text",sixteen);oversized.add(var(o));}expect(applyControlEdits(source,var(oversized),edited).failed(),"splitting text into operations cannot bypass the per-edit sixteen-command budget");
    buildProjectCommands(source,"set track 8 volume to 40 percent\ntranspose track 8 in pattern 1 down 2 semitones",draft);auto a=render(draft.project,assets,root,96000),b=render(source,assets,root,96000);double difference=0;for(int i=0;i<96000;++i)difference+=std::abs(a.getSample(0,i)-b.getSample(0,i));expect(a.getMagnitude(0,0,96000)>.001&&difference>1,"committed command parameters and pitches change actual rendered audio");
    auto file=root.getChildFile("project-commands.pulse");Project loaded;expect(saveProject(draft.project,file).wasOk()&&loadProject(file,loaded).wasOk()&&JSON::toString(projectToJson(loaded))==JSON::toString(projectToJson(draft.project)),"command results save as ordinary projects without a new project schema or parser dependency");
}
